import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";

// =========================================================================
// THEME
// =========================================================================
const COLORS = {
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "'JetBrains Mono', monospace";

const TRANSITION = 8;

// =========================================================================
// SCENE 1 — "Content shift in your space" — wave/pulse moving across
// =========================================================================
const SceneShift: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const cardIn = springIn(frame, fps, 4, "LIQUID");
  const pulseIn = springIn(frame, fps, 14, "SNAPPY");

  const BAR_COUNT = 24;

  const driftY = ambientDrift(frame, 3, 120, "shift-card");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_PRIMARY }}>
      <div
        style={{
          position: "absolute",
          left: "12%",
          top: "32%",
          width: "62%",
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px) scale(${interpolate(cardIn, [0, 1], [0.94, 1])})`,
          filter: `blur(${interpolate(cardIn, [0, 1], [10, 0])}px)`,
        }}
      >
        <div
          style={{
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.035,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.025,
          }}
        >
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.018,
              color: COLORS.textSubtle,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            // detecting shift
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "flex-end",
              gap: base * 0.006,
              height: base * 0.18,
            }}
          >
            {Array.from({ length: BAR_COUNT }).map((_, i) => {
              const barIn = staggeredSpring(
                frame,
                fps,
                i,
                10,
                1.2,
                "ELASTIC",
              );
              const phase = frame / 8 - i * 0.5;
              const wave = (Math.sin(phase) + 1) * 0.5;
              const envelopeFactor = i / BAR_COUNT;
              const targetH = base * (0.04 + wave * 0.13 * (0.4 + envelopeFactor));
              const h = targetH * barIn;
              const isAccent = i > BAR_COUNT * 0.62;
              return (
                <div
                  key={i}
                  style={{
                    flex: 1,
                    height: h,
                    background: isAccent ? COLORS.orange : "rgba(255,255,255,0.35)",
                    borderRadius: base * 0.004,
                  }}
                />
              );
            })}
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.012,
              opacity: pulseIn,
              transform: `translateY(${interpolate(pulseIn, [0, 1], [8, 0])}px)`,
            }}
          >
            <div
              style={{
                width: base * 0.012,
                height: base * 0.012,
                borderRadius: "50%",
                background: COLORS.orange,
                boxShadow: `0 0 ${base * 0.02}px ${COLORS.orange}`,
                opacity: 0.7 + Math.sin(frame / 6) * 0.3,
              }}
            />
            <div
              style={{
                flex: 1,
                height: 1,
                background: `linear-gradient(90deg, ${COLORS.orange}, transparent)`,
              }}
            />
            <div
              style={{
                fontFamily: FONT_MONO,
                fontSize: base * 0.016,
                color: COLORS.orange,
                letterSpacing: "0.1em",
              }}
            >
              SIGNAL +
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =========================================================================
// SCENE 2 — "Data before view counts" — data dashboard with rising metric
// =========================================================================
const SceneDataBeforeViews: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const dataCardIn = springIn(frame, fps, 4, "LIQUID");
  const viewsCardIn = springIn(frame, fps, 22, "GENTLE");
  const arrowIn = springIn(frame, fps, 38, "SNAPPY");

  const counterProgress = springIn(frame, fps, 12, "LIQUID");
  const counterValue = Math.round(interpolate(counterProgress, [0, 1], [0, 247]));

  const driftL = ambientDrift(frame, 2, 90, "data-card");
  const driftR = ambientDrift(frame, 1.5, 110, "views-card");

  const POINTS = 16;
  const trendPoints = Array.from({ length: POINTS }).map((_, i) => {
    const x = (i / (POINTS - 1)) * 100;
    const ease = i / (POINTS - 1);
    const y = 70 - ease * ease * 55 + Math.sin(i * 0.8) * 3;
    return { x, y };
  });
  const lineProgress = interpolate(counterProgress, [0, 1], [0, POINTS]);

  return (
    <AbsoluteFill style={{ fontFamily: FONT_PRIMARY }}>
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "24%",
          width: "46%",
          opacity: dataCardIn,
          transform: `translateY(${interpolate(dataCardIn, [0, 1], [40, driftL])}px) scale(${interpolate(dataCardIn, [0, 1], [0.94, 1])})`,
        }}
      >
        <div
          style={{
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.03,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.018,
          }}
        >
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.016,
              color: COLORS.orange,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            DATA
          </div>

          <div
            style={{
              fontFamily: FONT_MARKETING,
              fontWeight: 800,
              fontSize: base * 0.11,
              color: COLORS.text,
              lineHeight: 0.95,
              letterSpacing: "-0.03em",
              display: "flex",
              alignItems: "baseline",
              gap: base * 0.01,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            <span>{counterValue}</span>
            <span
              style={{
                fontSize: base * 0.04,
                color: COLORS.orange,
                background: COLORS.orangeTint,
                borderBottom: `2px solid ${COLORS.orange}`,
                padding: `0 ${base * 0.012}px`,
                borderRadius: base * 0.006,
                fontFamily: FONT_MARKETING,
              }}
            >
              ↑
            </span>
          </div>

          <svg
            viewBox="0 0 100 70"
            preserveAspectRatio="none"
            style={{ width: "100%", height: base * 0.09 }}
          >
            <path
              d={trendPoints
                .slice(0, Math.max(2, Math.floor(lineProgress)))
                .map((p, i) => (i === 0 ? `M${p.x},${p.y}` : `L${p.x},${p.y}`))
                .join(" ")}
              stroke={COLORS.orange}
              strokeWidth={1.5}
              fill="none"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d={
                trendPoints
                  .slice(0, Math.max(2, Math.floor(lineProgress)))
                  .map((p, i) => (i === 0 ? `M${p.x},${p.y}` : `L${p.x},${p.y}`))
                  .join(" ") +
                ` L${trendPoints[Math.max(1, Math.floor(lineProgress)) - 1]?.x ?? 0},70 L0,70 Z`
              }
              fill={COLORS.orangeTint}
            />
          </svg>

          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.014,
              color: COLORS.textSubtle,
              letterSpacing: "0.1em",
            }}
          >
            T-72h
          </div>
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: "55%",
          top: "44%",
          opacity: arrowIn,
          transform: `translateX(${interpolate(arrowIn, [0, 1], [-20, 0])}px)`,
        }}
      >
        <svg width={base * 0.05} height={base * 0.05} viewBox="0 0 24 24">
          <path
            d="M4 12 L18 12 M13 7 L18 12 L13 17"
            stroke={COLORS.orange}
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
          />
        </svg>
      </div>

      <div
        style={{
          position: "absolute",
          left: "61%",
          top: "30%",
          width: "32%",
          opacity: viewsCardIn,
          transform: `translateY(${interpolate(viewsCardIn, [0, 1], [40, driftR])}px) scale(${interpolate(viewsCardIn, [0, 1], [0.94, 1])})`,
        }}
      >
        <div
          style={{
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.025,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.014,
          }}
        >
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.014,
              color: COLORS.textSubtle,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            VIEWS
          </div>
          <div
            style={{
              fontFamily: FONT_MARKETING,
              fontWeight: 700,
              fontSize: base * 0.055,
              color: COLORS.textMuted,
              lineHeight: 0.95,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            12
          </div>
          <div
            style={{
              height: 2,
              background: "rgba(255,255,255,0.25)",
              borderRadius: 1,
            }}
          />
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.012,
              color: COLORS.textSubtle,
              letterSpacing: "0.1em",
            }}
          >
            T+0
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =========================================================================
// SCENE 3 — "What to film / what formats / which competitor" — three rows
// =========================================================================
const SceneThreeAnswers: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const cardIn = springIn(frame, fps, 4, "LIQUID");

  const ROWS = [
    { icon: "film", label: "FORMAT_A" },
    { icon: "layout", label: "FORMAT_B" },
    { icon: "user", label: "COMP_07" },
  ];

  const driftY = ambientDrift(frame, 2.5, 110, "answers-card");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_PRIMARY }}>
      <div
        style={{
          position: "absolute",
          left: "14%",
          top: "22%",
          width: "60%",
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px)`,
          filter: `blur(${interpolate(cardIn, [0, 1], [8, 0])}px)`,
        }}
      >
        <div
          style={{
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.032,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.022,
          }}
        >
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.016,
              color: COLORS.textSubtle,
              letterSpacing: "0.18em",
              textTransform: "uppercase",
            }}
          >
            // signals decoded
          </div>

          {ROWS.map((row, i) => {
            const rowIn = staggeredSpring(
              frame,
              fps,
              i,
              22,
              16,
              "ELASTIC",
            );
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: base * 0.018,
                  opacity: rowIn,
                  transform: `translateX(${interpolate(rowIn, [0, 1], [-30, 0])}px)`,
                }}
              >
                <svg width={base * 0.028} height={base * 0.028} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
                  <path
                    d="M5 12.5 L10 17.5 L19 7"
                    stroke={COLORS.orange}
                    strokeWidth={2.75}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill="none"
                    strokeDasharray={28}
                    strokeDashoffset={interpolate(rowIn, [0, 1], [28, 0])}
                  />
                </svg>

                <div
                  style={{
                    width: base * 0.06,
                    height: base * 0.045,
                    background: "#2a2b2c",
                    border: `1px solid ${COLORS.border}`,
                    borderRadius: base * 0.006,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                  }}
                >
                  {row.icon === "film" && (
                    <svg width={base * 0.022} height={base * 0.022} viewBox="0 0 24 24">
                      <rect x="3" y="6" width="18" height="12" rx="1" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                      <path d="M3 9 L21 9 M3 15 L21 15" stroke={COLORS.orange} strokeWidth={1} />
                    </svg>
                  )}
                  {row.icon === "layout" && (
                    <svg width={base * 0.022} height={base * 0.022} viewBox="0 0 24 24">
                      <rect x="4" y="4" width="7" height="16" rx="1" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                      <rect x="13" y="4" width="7" height="7" rx="1" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                      <rect x="13" y="13" width="7" height="7" rx="1" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                    </svg>
                  )}
                  {row.icon === "user" && (
                    <svg width={base * 0.022} height={base * 0.022} viewBox="0 0 24 24">
                      <circle cx="12" cy="9" r="3.5" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                      <path d="M5 20 C 5 15, 19 15, 19 20" stroke={COLORS.orange} strokeWidth={1.5} fill="none" />
                    </svg>
                  )}
                </div>

                <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: base * 0.006 }}>
                  <div
                    style={{
                      width: `${interpolate(rowIn, [0, 1], [0, 70])}%`,
                      height: base * 0.012,
                      background: "rgba(255,255,255,0.3)",
                      borderRadius: base * 0.003,
                    }}
                  />
                  <div
                    style={{
                      width: `${interpolate(rowIn, [0, 1], [0, 45])}%`,
                      height: base * 0.008,
                      background: "rgba(255,255,255,0.18)",
                      borderRadius: base * 0.003,
                    }}
                  />
                </div>

                <div
                  style={{
                    fontFamily: FONT_MONO,
                    fontSize: base * 0.014,
                    color: COLORS.orange,
                    letterSpacing: "0.1em",
                    background: COLORS.orangeTint,
                    padding: `${base * 0.005}px ${base * 0.012}px`,
                    borderRadius: base * 0.004,
                    opacity: rowIn,
                  }}
                >
                  {row.label}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =========================================================================
// SCENE DURATIONS (25fps)
// Original total: D1+D2+D3+D4+D5 + TRANSITION*4 = 64+86+115+71+127 + 32 = 495
// New total must match 495. Distribute across remaining 3 scenes.
// D1=64, D2=86, D3=115 = 265. Remaining = 495 - 265 - TRANSITION*2 = 214
// Extend the three scenes to hold longer instead.
// =========================================================================
const D1 = 130;
const D2 = 150;
const D3 = 199;

// =========================================================================
// COMPOSITION
// =========================================================================
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={D1 + TRANSITION}>
        <SceneShift />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={D2 + TRANSITION}>
        <SceneDataBeforeViews />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={D3}>
        <SceneThreeAnswers />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export const fps = 25;
export const durationInFrames = D1 + D2 + D3 + TRANSITION * 2;

export default MainComposition;
